//! One-click ChemSSH install / update on a remote profile.
//!
//! The heavy lifting happens in a shell script generated by `core-installer` and run over SSH.
//! This module connects, plans (install / fast update / full update / repair), streams the
//! script output into a per-profile job log, and falls back to "download locally and upload
//! over SFTP" when the server cannot reach GitHub.

use std::collections::HashMap;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use core_config::{proxy_env_pairs, EnvPair, Profile, ProfileStore};
use core_installer::{
    archive_urls, build_install_script, build_probe_script, manifest_urls, plan, proxy_exports,
    shell_quote, Action, InstallDir, InstallerOptions, Manifest, RemoteProbe, ScriptParams,
    EXIT_DOWNLOAD_FAILED,
};
use core_ssh::{HostKeyPolicy, KnownHostsVerifier, ReverseProxyChannel, SshConnection};
use russh_sftp::protocol::OpenFlags;
use serde::Serialize;
use sha2::{Digest, Sha256};
use tauri::State;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::sync::mpsc;

use crate::commands::sessions::{format_ssh_error, load_ssh_credentials};
use crate::state::AppState;

const MAX_JOB_LINES: usize = 4000;
const INSTALL_TIMEOUT: Duration = Duration::from_secs(60 * 40);
const CHECK_TIMEOUT: Duration = Duration::from_secs(10);
const PROBE_EXEC_TIMEOUT: Duration = Duration::from_secs(5);

// ---------------------------------------------------------------------------------------------
// Job bookkeeping
// ---------------------------------------------------------------------------------------------

#[derive(Default)]
struct JobInner {
    phase: String,
    message: String,
    lines: Vec<String>,
    base: usize,
    pending: String,
}

pub struct InstallerJob {
    inner: Mutex<JobInner>,
}

impl InstallerJob {
    fn new() -> Arc<Self> {
        Arc::new(Self {
            inner: Mutex::new(JobInner {
                phase: "running".into(),
                ..Default::default()
            }),
        })
    }

    fn push_line(&self, line: impl Into<String>) {
        let mut inner = self.inner.lock().unwrap();
        push_line_locked(&mut inner, line.into());
    }

    /// Accepts arbitrary output chunks and records complete lines.
    fn push_chunk(&self, chunk: &str) {
        let mut inner = self.inner.lock().unwrap();
        inner.pending.push_str(chunk);
        while let Some(pos) = inner.pending.find('\n') {
            let line: String = inner.pending.drain(..=pos).collect();
            push_line_locked(&mut inner, line);
        }
    }

    fn finish(&self, phase: &str, message: impl Into<String>) {
        let mut inner = self.inner.lock().unwrap();
        if !inner.pending.is_empty() {
            let rest = std::mem::take(&mut inner.pending);
            push_line_locked(&mut inner, rest);
        }
        inner.phase = phase.to_string();
        inner.message = message.into();
    }

    fn is_running(&self) -> bool {
        self.inner.lock().unwrap().phase == "running"
    }

    fn progress(&self, since: usize) -> InstallerProgress {
        let inner = self.inner.lock().unwrap();
        let end = inner.base + inner.lines.len();
        let from = since.max(inner.base);
        let lines = if from >= end {
            Vec::new()
        } else {
            inner.lines[from - inner.base..].to_vec()
        };
        InstallerProgress {
            phase: inner.phase.clone(),
            message: inner.message.clone(),
            lines,
            next: end,
        }
    }
}

fn push_line_locked(inner: &mut JobInner, line: String) {
    let trimmed = line.trim_end_matches(['\r', '\n']).to_string();
    if trimmed.is_empty() {
        return;
    }
    if inner.lines.len() >= MAX_JOB_LINES {
        inner.lines.remove(0);
        inner.base += 1;
    }
    inner.lines.push(trimmed);
}

#[derive(Default)]
pub struct InstallerManager {
    jobs: Mutex<HashMap<String, Arc<InstallerJob>>>,
}

impl InstallerManager {
    fn get(&self, profile_id: &str) -> Option<Arc<InstallerJob>> {
        self.jobs.lock().unwrap().get(profile_id).cloned()
    }

    /// Registers a new job unless one is already running for the profile.
    fn begin(&self, profile_id: &str) -> Result<Arc<InstallerJob>, String> {
        let mut jobs = self.jobs.lock().unwrap();
        if let Some(existing) = jobs.get(profile_id) {
            if existing.is_running() {
                return Err("an install or update is already running for this profile".into());
            }
        }
        let job = InstallerJob::new();
        jobs.insert(profile_id.to_string(), job.clone());
        Ok(job)
    }
}

