#[derive(Debug, Clone, Serialize)]
pub struct InstallerCheck {
    pub install_dir: String,
    pub installed: bool,
    pub installed_version: String,
    pub latest_version: String,
    pub action: Action,
    /// True when an update also has to reinstall Python dependencies.
    pub deps_changed: bool,
    pub venv_ok: bool,
}

#[derive(Debug, Clone, Serialize)]
pub struct InstallerProgress {
    pub phase: String,
    pub message: String,
    pub lines: Vec<String>,
    pub next: usize,
}

// ---------------------------------------------------------------------------------------------
// Local helpers
// ---------------------------------------------------------------------------------------------

async fn run_local_curl(args: &[String], timeout_dur: Duration) -> Result<Vec<u8>, String> {
    let mut cmd = tokio::process::Command::new("curl");
    cmd.args(args)
        .stdin(std::process::Stdio::null())
        .kill_on_drop(true);
    #[cfg(windows)]
    {
        cmd.creation_flags(0x0800_0000); // CREATE_NO_WINDOW
    }
    let output = tokio::time::timeout(timeout_dur, cmd.output())
        .await
        .map_err(|_| format!("local curl timed out after {}s", timeout_dur.as_secs()))?
        .map_err(|e| format!("could not run local curl: {e}"))?;
    if output.status.success() {
        Ok(output.stdout)
    } else {
        Err(format!(
            "curl exited with {}: {}",
            output.status,
            String::from_utf8_lossy(&output.stderr).trim()
        ))
    }
}

fn local_curl_args(
    url: &str,
    proxy: Option<&str>,
    connect_timeout: u32,
    max_time: u32,
    out: Option<&str>,
) -> Vec<String> {
    let mut args: Vec<String> = vec![
        "-fsSL".into(),
        "--connect-timeout".into(),
        connect_timeout.to_string(),
        "--max-time".into(),
        max_time.to_string(),
    ];
    if let Some(proxy) = proxy {
        args.push("-x".into());
        args.push(proxy.to_string());
    }
    if let Some(out) = out {
        args.push("-o".into());
        args.push(out.to_string());
    }
    args.push(url.to_string());
    args
}

#[cfg(test)]
fn sha256_hex(bytes: &[u8]) -> String {
    hex::encode(Sha256::digest(bytes))
}

/// Keeps the reverse proxy channel alive for the duration of one operation.
struct ProxyGuard {
    channel: Option<ReverseProxyChannel>,
    env: Vec<EnvPair>,
    local_url: Option<String>,
}

impl ProxyGuard {
    async fn start(connection: &SshConnection, profile: &Profile) -> (Self, Option<String>) {
        if !profile.proxy_active() {
            return (
                Self {
                    channel: None,
                    env: Vec::new(),
                    local_url: None,
                },
                None,
            );
        }
        let lp = profile.local_proxy.normalized();
        match connection.start_reverse_proxy(lp.address()).await {
            Ok(channel) => {
                let env = proxy_env_pairs(&channel.proxy_url, &lp.no_proxy);
                (
                    Self {
                        channel: Some(channel),
                        env,
                        local_url: Some(lp.url()),
                    },
                    None,
                )
            }
            Err(err) => (
                Self {
                    channel: None,
                    env: Vec::new(),
                    local_url: Some(lp.url()),
                },
                Some(format!(
                    "local proxy channel unavailable, continuing without it: {err}"
                )),
            ),
        }
    }

    async fn close(&mut self) {
        if let Some(mut channel) = self.channel.take() {
            channel.close().await;
        }
    }
}

async fn connect(
    state: &AppState,
    profile: &Profile,
    policy: Option<HostKeyPolicy>,
) -> Result<SshConnection, String> {
    if profile.is_local() {
        return Err("one-click install needs a remote profile".into());
    }
    let state_clone = state.clone();
    let profile_clone = profile.clone();
    let creds =
        tokio::task::spawn_blocking(move || load_ssh_credentials(&state_clone, &profile_clone))
            .await
            .map_err(|e| format!("load credentials task failed: {e}"))??;
    let verifier = KnownHostsVerifier::new(
        &state.known_hosts_path,
        &profile.ssh_host,
        profile.ssh_port,
        policy.unwrap_or(HostKeyPolicy::Strict),
    );
    SshConnection::connect(profile, &creds, verifier)
        .await
        .map_err(format_ssh_error)
}

async fn exec_script(
    connection: &SshConnection,
    script: &str,
    timeout_dur: Duration,
) -> Result<String, String> {
    let out = connection
        .exec_with_stdin("/bin/sh -s", script.as_bytes(), timeout_dur)
        .await
        .map_err(|e| e.to_string())?;
    if out.exit_code.unwrap_or(0) != 0 {
        return Err(format!(
            "remote probe failed: {}",
            out.stderr.trim().lines().last().unwrap_or("unknown error")
        ));
    }
    Ok(out.stdout)
}

/// Release manifest from GitHub: tries the official URL first, then the user-configured
/// proxy prefix (if any), checking the server first (curl or wget) and falling back to local curl.
/// Returns `(manifest, used_proxy_prefix)`.
async fn fetch_manifest(
    connection: &SshConnection,
    proxy: &ProxyGuard,
    proxy_prefix: &str,
    per_try_secs: u32,
) -> Result<(Manifest, bool), String> {
    let urls = manifest_urls(proxy_prefix);
    let exports = proxy_exports(&proxy.env).replace('\n', "; ");
    let mut errors = Vec::new();
    let connect_secs = per_try_secs.min(3).max(1);
    let exec_timeout = Duration::from_secs((per_try_secs as u64).saturating_add(2));

    for (idx, url) in urls.iter().enumerate() {
        let used_proxy_prefix = idx > 0;
        let q = shell_quote(url);
        let remote_cmd = format!(
            "{exports}if command -v curl >/dev/null 2>&1; then curl -fsSL --connect-timeout {connect_secs} --max-time {per_try_secs} {q}; \
             elif command -v wget >/dev/null 2>&1; then wget -q -T {per_try_secs} --tries=1 -O - {q}; \
             else exit 127; fi"
        );
        match connection
            .exec_command_timeout(&format!("sh -c {}", shell_quote(&remote_cmd)), exec_timeout)
            .await
        {
            Ok(out) if out.exit_code == Some(0) => match Manifest::parse(&out.stdout) {
                Ok(m) => return Ok((m, used_proxy_prefix)),
                Err(e) => errors.push(format!("remote {url}: {e}")),
            },
            Ok(out) => errors.push(format!("remote {url}: exit {:?}", out.exit_code)),
            Err(e) => errors.push(format!("remote {url}: {e}")),
        }

        let args = local_curl_args(
            url,
            proxy.local_url.as_deref(),
            connect_secs,
            per_try_secs,
            None,
        );
        match run_local_curl(&args, exec_timeout).await {
            Ok(bytes) => match Manifest::parse(&String::from_utf8_lossy(&bytes)) {
                Ok(m) => return Ok((m, used_proxy_prefix)),
                Err(e) => errors.push(format!("local {url}: {e}")),
            },
            Err(e) => errors.push(format!("local {url}: {e}")),
        }
    }

    Err(format!(
        "could not fetch the release manifest ({}). \
         Enable the local network proxy, set a GitHub download proxy prefix, or check GitHub access",
        errors.join("; ")
    ))
}

struct Prepared {
    connection: Arc<SshConnection>,
    profile: Profile,
    options: InstallerOptions,
    dir: InstallDir,
    probe: RemoteProbe,
    manifest: Manifest,
    manifest_via_proxy_prefix: bool,
    action: Action,
    proxy: ProxyGuard,
    proxy_warning: Option<String>,
}

impl Prepared {
    async fn release(mut self) {
        self.proxy.close().await;
        self.connection.disconnect().await;
    }

    fn check(&self) -> InstallerCheck {
        InstallerCheck {
            install_dir: self.dir.resolve(&self.probe.home),
            installed: self.probe.record.is_some(),
            installed_version: self
                .probe
                .record
                .as_ref()
                .map(|r| r.version.clone())
                .unwrap_or_default(),
            latest_version: self.manifest.version.clone(),
            action: self.action,
            deps_changed: self.action == Action::UpdateFull,
            venv_ok: self.probe.venv_ok,
        }
    }
}

async fn prepare(
    state: &AppState,
    profile_id: &str,
    options: InstallerOptions,
    policy: Option<HostKeyPolicy>,
    force_repair: bool,
    manifest_per_try_secs: u32,
) -> Result<Prepared, String> {
    options.validate().map_err(|e| e.to_string())?;
    let dir = options.dir().map_err(|e| e.to_string())?;
    let profiles_store = Arc::clone(&state.profiles);
    let pid = profile_id.to_string();
    let profile = tokio::task::spawn_blocking(move || profiles_store.get(&pid))
        .await
        .map_err(|e| format!("load profile task failed: {e}"))?
        .map_err(|e| e.to_string())?;
    let connection = Arc::new(connect(state, &profile, policy).await?);
    let (mut proxy, proxy_warning) = ProxyGuard::start(&connection, &profile).await;

    let proxy_prefix = options.proxy_prefix().to_string();
    let result: Result<(RemoteProbe, Manifest, bool), String> = async {
        let probe = RemoteProbe::parse(
            &exec_script(&connection, &build_probe_script(&dir), PROBE_EXEC_TIMEOUT).await?,
        );
        let (manifest, via_proxy) =
            fetch_manifest(&connection, &proxy, &proxy_prefix, manifest_per_try_secs).await?;
        Ok((probe, manifest, via_proxy))
    }
    .await;

    match result {
        Ok((probe, manifest, manifest_via_proxy_prefix)) => {
            let action = plan(
                probe.record.as_ref(),
                probe.venv_ok,
                &manifest,
                force_repair,
            );
            Ok(Prepared {
                connection,
                profile,
                options,
                dir,
                probe,
                manifest,
                manifest_via_proxy_prefix,
                action,
                proxy,
                proxy_warning,
            })
        }
        Err(err) => {
            proxy.close().await;
            connection.disconnect().await;
            Err(err)
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Background run
// ---------------------------------------------------------------------------------------------

async fn run_script_streaming(
    connection: &SshConnection,
    script: &str,
    job: &Arc<InstallerJob>,
) -> Result<Option<u32>, String> {
    let (tx, mut rx) = mpsc::channel::<String>(256);
    let forward_job = job.clone();
    let forwarder = tokio::spawn(async move {
        while let Some(chunk) = rx.recv().await {
            forward_job.push_chunk(&chunk);
        }
    });
    let shell_cmd =
        "sh -c 'if command -v bash >/dev/null 2>&1; then exec bash -s; else exec /bin/sh -s; fi'";
    let result = tokio::time::timeout(
        INSTALL_TIMEOUT,
        connection.exec_streaming_stdin(shell_cmd, script.as_bytes(), tx),
    )
    .await;
    let _ = forwarder.await;
    match result {
        Ok(Ok(code)) => Ok(code),
        Ok(Err(e)) => Err(e.to_string()),
        Err(_) => Err("install timed out".into()),
    }
}

/// Downloads the archive on this machine, verifies it and uploads it over SFTP.
/// Returns the absolute remote path of the uploaded file.
async fn download_locally_and_upload(
    prep: &Prepared,
    job: &Arc<InstallerJob>,
) -> Result<String, String> {
    let archive = prep.manifest.archive().map_err(|e| e.to_string())?;
    let urls = archive_urls(
        &prep.manifest.tag,
        &archive.name,
        prep.options.proxy_prefix(),
    );
    let local_path: PathBuf = std::env::temp_dir().join(format!(
        "chemssh-installer-{}-{}",
        std::process::id(),
        archive.name
    ));
    let proxy = prep.proxy.local_url.clone();
    let mut downloaded = false;
    for url in &urls {
        job.push_line(format!("[installer] downloading on this computer: {url}"));
        let args = local_curl_args(
            url,
            proxy.as_deref(),
            10,
            600,
            Some(&local_path.to_string_lossy()),
        );
        match run_local_curl(&args, Duration::from_secs(620)).await {
            Ok(_) => {
                downloaded = true;
                break;
            }
            Err(e) => job.push_line(format!("[installer] local download failed: {e}")),
        }
    }
    if !downloaded {
        let _ = std::fs::remove_file(&local_path);
        return Err("could not download the release archive on this computer either".into());
    }
    let upload_result = async {
        let mut local_file = tokio::fs::File::open(&local_path)
            .await
            .map_err(|e| format!("open downloaded archive: {e}"))?;
        let mut hasher = Sha256::new();
        let mut buf = vec![0u8; 256 * 1024];
        loop {
            let n = local_file
                .read(&mut buf)
                .await
                .map_err(|e| format!("read downloaded archive: {e}"))?;
            if n == 0 {
                break;
            }
            hasher.update(&buf[..n]);
        }
        let digest = hex::encode(hasher.finalize());
        if !digest.eq_ignore_ascii_case(&archive.sha256) {
            return Err(
                "sha256 mismatch for the locally downloaded archive; refusing to upload".into(),
            );
        }
        job.push_line("[installer] checksum verified, uploading to the server");

        let base = prep.dir.resolve(&prep.probe.home);
        let upload_dir = format!("{base}/.upload");
        let mkdir = format!("mkdir -p {}", shell_quote(&upload_dir));
        let out = prep
            .connection
            .exec_command(&mkdir)
            .await
            .map_err(|e| e.to_string())?;
        if out.exit_code != Some(0) {
            return Err(format!(
                "could not create {upload_dir}: {}",
                out.stderr.trim()
            ));
        }
        let target = format!("{upload_dir}/{}", archive.name);
        let sftp = prep
            .connection
            .open_sftp()
            .await
            .map_err(|e| e.to_string())?;
        let mut remote_file = sftp
            .open_with_flags(
                &target,
                OpenFlags::WRITE | OpenFlags::CREATE | OpenFlags::TRUNCATE,
            )
            .await
            .map_err(|e| format!("open {target}: {e}"))?;

        let mut reader = tokio::fs::File::open(&local_path)
            .await
            .map_err(|e| format!("reopen downloaded archive: {e}"))?;
        loop {
            let n = reader
                .read(&mut buf)
                .await
                .map_err(|e| format!("read downloaded archive: {e}"))?;
            if n == 0 {
                break;
            }
            remote_file
                .write_all(&buf[..n])
                .await
                .map_err(|e| format!("upload failed: {e}"))?;
        }
        remote_file
            .shutdown()
            .await
            .map_err(|e| format!("close upload: {e}"))?;
        Ok(target)
    }
    .await;
    let _ = std::fs::remove_file(&local_path);
    upload_result
}

async fn run_job(prep: Prepared, job: Arc<InstallerJob>) {
    let outcome = run_job_inner(&prep, &job).await;
    match outcome {
        Ok(()) => job.finish(
            "done",
            format!("ChemSSH {} is ready", prep.manifest.version),
        ),
        Err(err) => {
            job.push_line(format!("[installer] ERROR: {err}"));
            job.finish("failed", err);
        }
    }
    prep.release().await;
}

async fn run_job_inner(prep: &Prepared, job: &Arc<InstallerJob>) -> Result<(), String> {
    let archive = prep.manifest.archive().map_err(|e| e.to_string())?.clone();
    let urls = archive_urls(
        &prep.manifest.tag,
        &archive.name,
        prep.options.proxy_prefix(),
    );
    let pre_start = if prep.options.ignore_pre_start {
        ""
    } else {
        prep.profile.pre_start_commands.as_str()
    };
    if let Some(warning) = &prep.proxy_warning {
        job.push_line(format!("[installer] {warning}"));
    }
    if prep.manifest_via_proxy_prefix {
        job.push_line(
            "[installer] notice: release manifest was fetched via the configured download proxy",
        );
    }
    job.push_line(format!(
        "[installer] {} ChemSSH {} in {}",
        match prep.action {
            Action::Install => "installing",
            Action::Repair => "repairing",
            Action::UpdateFast => "updating files of",
            Action::UpdateFull => "updating (with dependencies)",
            Action::UpToDate => "checking",
        },
        prep.manifest.version,
        prep.dir.resolve(&prep.probe.home)
    ));

    let build = |uploaded: Option<&str>| {
        build_install_script(&ScriptParams {
            dir: &prep.dir,
            action: prep.action,
            manifest: &prep.manifest,
            archive: &archive,
            urls: &urls,
            uploaded,
            options: &prep.options,
            pre_start,
            proxy_env: &prep.proxy.env,
        })
    };

    let code = run_script_streaming(&prep.connection, &build(None), job).await?;
    match code {
        Some(0) => Ok(()),
        Some(c) if c == EXIT_DOWNLOAD_FAILED => {
            job.push_line("[installer] the server cannot download the release, trying local download + upload");
            let uploaded = download_locally_and_upload(prep, job).await?;
            let code = run_script_streaming(&prep.connection, &build(Some(&uploaded)), job).await?;
            if code == Some(0) {
                Ok(())
            } else {
                Err(format!("installer script exited with status {code:?}"))
            }
        }
        other => Err(format!("installer script exited with status {other:?}")),
    }
}

// ---------------------------------------------------------------------------------------------
// Commands
// ---------------------------------------------------------------------------------------------

#[tauri::command]
pub async fn installer_check(
    state: State<'_, AppState>,
    profile_id: String,
    options: InstallerOptions,
    host_key_policy: Option<HostKeyPolicy>,
) -> Result<InstallerCheck, String> {
    let app_state = state.inner().clone();
    // Run the probe in an isolated background task capped at CHECK_TIMEOUT (10s)
    // so slow networks or hung remote endpoints never block saving profiles or other UI actions.
    let task = tokio::spawn(async move {
        let prep = prepare(&app_state, &profile_id, options, host_key_policy, false, 3).await?;
        let check = prep.check();
        prep.release().await;
        Ok::<InstallerCheck, String>(check)
    });
    let abort_handle = task.abort_handle();
    match tokio::time::timeout(CHECK_TIMEOUT, task).await {
        Ok(Ok(result)) => result,
        Ok(Err(join_err)) => Err(format!("installer check task failed: {join_err}")),
        Err(_) => {
            abort_handle.abort();
            Err(format!(
                "check timed out after {}s; verify SSH connectivity or configure a download proxy",
                CHECK_TIMEOUT.as_secs()
            ))
        }
    }
}

/// `mode` is `auto` (install or update as needed) or `repair` (rebuild the virtualenv).
#[tauri::command]
pub async fn installer_run(
    state: State<'_, AppState>,
    profile_id: String,
    options: InstallerOptions,
    mode: Option<String>,
    host_key_policy: Option<HostKeyPolicy>,
) -> Result<InstallerCheck, String> {
    if state
        .installer
        .get(&profile_id)
        .map(|j| j.is_running())
        .unwrap_or(false)
    {
        return Err("an install or update is already running for this profile".into());
    }
    let session_gate = state.sessions.lock_for_install(&profile_id).await?;
    let force_repair = mode.as_deref() == Some("repair");
    let prep = prepare(
        &state,
        &profile_id,
        options,
        host_key_policy,
        force_repair,
        6,
    )
    .await?;
    let check = prep.check();
    if prep.action == Action::UpToDate {
        prep.release().await;
        return Ok(check);
    }
    let job = match state.installer.begin(&profile_id) {
        Ok(job) => job,
        Err(err) => {
            prep.release().await;
            return Err(err);
        }
    };
    tokio::spawn(async move {
        let _session_gate = session_gate;
        run_job(prep, job).await;
    });
    Ok(check)
}

#[tauri::command]
pub fn installer_status(
    state: State<'_, AppState>,
    profile_id: String,
    since: Option<usize>,
) -> InstallerProgress {
    match state.installer.get(&profile_id) {
        Some(job) => job.progress(since.unwrap_or(0)),
        None => InstallerProgress {
            phase: "idle".into(),
            message: String::new(),
            lines: Vec::new(),
            next: 0,
        },
    }
}

/// Points the profile's commands at the installed ChemSSH (after the user confirmed).
#[tauri::command]
pub fn installer_apply_profile(
    state: State<'_, AppState>,
    profile_id: String,
    options: InstallerOptions,
) -> Result<Profile, String> {
    let dir = options.dir().map_err(|e| e.to_string())?;
    let mut profile = state.profiles.get(&profile_id).map_err(|e| e.to_string())?;
    if profile.is_local() {
        return Err("one-click install needs a remote profile".into());
    }
    let expr = dir.shell_expr();
    let (pre_start, start) = profile_commands(&profile.pre_start_commands, &expr);
    profile.pre_start_commands = pre_start;
    profile.start_command = start;
    profile.validate().map_err(|e| e.to_string())?;
    state.profiles.save(profile).map_err(|e| e.to_string())
}

fn profile_commands(existing_pre_start: &str, dir_expr: &str) -> (String, String) {
    let cd_line = format!("cd \"{dir_expr}/app\"");
    let mut pre_start = existing_pre_start
        .trim_end_matches(['\r', '\n'])
        .to_string();
    if !pre_start.lines().any(|l| l.trim() == cd_line) {
        if !pre_start.is_empty() {
            pre_start.push('\n');
        }
        pre_start.push_str(&cd_line);
    }
    let start = format!(
        "source \"{dir_expr}/.venv/bin/activate\"\nunset PS1\nexport CONDA_CHANGEPS1=false\nexport VIRTUAL_ENV_DISABLE_PROMPT=1\nchemssh --config \"{dir_expr}/config.yaml\""
    );
    (pre_start, start)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn job_splits_chunks_into_lines_and_pages() {
        let job = InstallerJob::new();
        job.push_chunk("[installer] one\n[install");
        job.push_chunk("er] two\n\n");
        let p = job.progress(0);
        assert_eq!(p.lines, vec!["[installer] one", "[installer] two"]);
        assert_eq!(p.next, 2);
        job.push_line("three");
        assert_eq!(job.progress(2).lines, vec!["three"]);
        assert!(job.progress(3).lines.is_empty());
        assert_eq!(job.progress(0).phase, "running");
        job.finish("done", "ok");
        assert!(!job.is_running());
    }

    #[test]
    fn job_flushes_partial_line_on_finish() {
        let job = InstallerJob::new();
        job.push_chunk("no newline");
        job.finish("failed", "x");
        assert_eq!(job.progress(0).lines, vec!["no newline"]);
    }

    #[test]
    fn manager_rejects_concurrent_runs() {
        let m = InstallerManager::default();
        let first = m.begin("p1").unwrap();
        assert!(m.begin("p1").is_err());
        assert!(m.begin("p2").is_ok());
        first.finish("done", "");
        assert!(m.begin("p1").is_ok());
    }

    #[test]
    fn profile_commands_use_installed_layout_and_keep_existing_pre_start() {
        let (pre, start) = profile_commands("module load python\n", "$HOME/.chemssh");
        assert_eq!(pre, "module load python\ncd \"$HOME/.chemssh/app\"");
        assert!(start.starts_with("source \"$HOME/.chemssh/.venv/bin/activate\"\n"));
        assert!(start.ends_with("chemssh --config \"$HOME/.chemssh/config.yaml\""));
        let (pre_again, _) = profile_commands(&pre, "$HOME/.chemssh");
        assert_eq!(pre_again, pre);
        let (empty, _) = profile_commands("", "$HOME/x");
        assert_eq!(empty, "cd \"$HOME/x/app\"");
    }

    #[test]
    fn sha256_matches_known_vector() {
        assert_eq!(
            sha256_hex(b"abc"),
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
    }
}
